-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromePoolFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- SetCustomFee(address,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_pool_factory__set_custom_fee',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as pool,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as fee
from {{ source('chain_base', 'logs') }}
where topic0 = '0xae468ce586f9a87660fdffc1448cee942042c16ae2f02046b134b5224f31936b'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_pool_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
